css:
body {
	margin: 0;
	font-family: sans-serif;
}

.page.mk-870fjj {
				padding: 24px;
				background: #f8f9fa;
			}
			.heading.mk-870fjj {
				font-size: 26px;
				font-weight: 700;
				color: #212529;
			}
			.sizes.mk-870fjj {
				display: flex;
				flex-direction: column;
				gap: 8px;
				margin-top: 16px;
			}
			.size.mk-870fjj {
				display: block;
				width: 100%;
				padding: 10px 16px;
				border: 1px solid #ced4da;
				border-radius: 10px;
				background: #ffffff;
				color: #212529;
				font-family: inherit;
				font-size: 17px;
				text-align: left;
			}
			.size[aria-pressed='true'].mk-870fjj {
				padding: 18px 16px;
				border: 2px solid #264653;
				background: #e9f5f9;
				font-weight: 700;
			}
			.footer.mk-870fjj {
				margin-top: 24px;
				padding-top: 12px;
				border-top: 1px solid #adb5bd;
				color: #495057;
				font-size: 15px;
			}
